var a=`0275-prekmurska-gibanica`;var s=`world-0275`;var n=`SI`;var i=`southern-europe`;var r=8;var o=103;var l={en:`Prekmurska Gibanica`,ua:`Прекмурська гібаніца`};var g={en:`A traditional Slovenia dish made with all-purpose flour, chicken egg, poppy seeds, walnut. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Словенія. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, мак, волоський горіх. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,350,`g`],[`chicken-egg`,2,`pcs`],[`water`,140,`ml`],[`table-salt`,4,`g`]]},{en:`Prepare separate poppy-seed, walnut, grated-apple and sweet farmer-cheese fillings; do not mix them together, as the alternating layers define Prekmurska gibanica.`,ua:`Приготуйте окремо макову, горіхову, яблучну та солодку сирну начинки; не змішуйте їх, адже чергування шарів визначає прекмурську гібаніцу.`,t:[`chopping`,`mixing`],m:8,i:[[`poppy-seeds`,120,`g`],[`white-granulated-sugar`,95,`g`],[`walnut`,115,`g`],[`apple`,250,`g`],[`farmer-cheese`,320,`g`]]},{en:`Line the tin with pastry, then alternate layers of poppy seeds, cottage cheese, walnuts and apples, separating with thin sheets of pastry; dot with butter and sour cream.`,ua:`Вистеліть форму тістом, потім чергуйте шари маку, сиру, горіхів і яблук, розділяючи їх тонкими листами тіста; додавайте трохи масла й сметани.`,t:[`layered-assembly`],m:17,i:[[`phyllo-pastry`,180,`g`],[`raisin`,100,`g`],[`sour-cream`,150,`g`],[`unsalted-butter`,80,`g`]]},{en:`Bake at 175–180°C until the layers are cooked and the pastry golden, about 50–55 minutes; cool slightly before cutting.`,ua:`Випікайте при 175–180°C до готовності начинки та золотистості тіста приблизно 50–55 хвилин; трохи охолодіть перед нарізанням.`,t:[`baking`],m:53,i:[]}];var p={slug:a,id:s,country:`SI`,region:i,servings:8,minutes:103,title:l,text:g,steps:u};export{n as country,p as default,s as id,o as minutes,i as region,r as servings,a as slug,u as steps,g as text,l as title};